8	/// Returns the process exit code (0 = success, 2 = extraction reported an
9	/// error-severity diagnostic) rather than calling `std::process::exit`
10	/// directly — keeps the exit decision testable and lets `main()` be the only
11	/// place that actually terminates the process.
12	pub fn cmd_extract(args: crate::ExtractArgs, quiet: bool, config_path: Option<&str>) -> Result<i32> {
13	    use indicatif::{ProgressBar, ProgressStyle};
14	
15	    let html_attributes = args.html_attributes.map(|m| match m {
16	        crate::HtmlAttributeModeArg::Curated => "curated",
17	        crate::HtmlAttributeModeArg::Full => "full",
18	        crate::HtmlAttributeModeArg::None => "none",
19	    });
20	    let options = build_options(BuildOptionsArgs {
21	        src: &args.src,
22	        cache_dir: args.cache_dir.as_deref(),
23	        no_cache: args.no_cache,
24	        html_attributes,
25	        config_path,
26	        extra_builtins: &args.extra_builtins,
27	        load_dependencies: args.load_dependencies,
28	        no_load_dependencies: args.no_load_dependencies,
29	        collapse_inherited_props: args.collapse_inherited_props.map(Into::into),
30	    })?;
31	    let mut options = options;
32	    if args.experimental_semantic_types {
33	        options.experimental_semantic_types = true;
34	    }
35	    if let Some(path) = &args.tsc_path {
36	        options.semantic_tsc_path = Some(path.into());
37	    }
38	
39	    let pb = if !quiet && !args.json {
40	        let pb = ProgressBar::new_spinner();
41	        pb.set_style(ProgressStyle::default_spinner().template("{spinner:.cyan} {msg}").into_diagnostic()?);
42	        pb.set_message("Extracting...");
43	        pb.enable_steady_tick(std::time::Duration::from_millis(80));
44	        Some(pb)
45	    } else {
46	        None
47	    };
48	
49	    let mut output = caliper_docgen_core::pipeline::extract(&options);
50	    if options.experimental_semantic_types {
51	        apply_semantic_backend(&options, &mut output);
52	    }
53	
54	    if let Some(pb) = pb {
55	        pb.finish_and_clear();
56	    }
57	
58	    // --json ignores --out/--format — see ExtractArgs::json's doc comment.
59	    if args.json {
60	        let mut stdout = std::io::BufWriter::with_capacity(1 << 16, std::io::stdout().lock());
61	        caliper_docgen_core::pipeline::write_extraction_output_json(&output, &mut stdout).into_diagnostic()?;
62	        writeln!(stdout).and_then(|()| stdout.flush()).into_diagnostic()?;
63	    } else {
64	        if !quiet {
65	            print_summary(&output, quiet);
66	            print_diagnostics(&output.diagnostics);
67	        }
68	
69	        let json = match args.format {
70	            crate::OutputFormat::Canonical => serde_json::to_string_pretty(&output).into_diagnostic()?,
71	            crate::OutputFormat::Rdt => serialize_rdt(&output, args.include_unexported).into_diagnostic()?,
72	            crate::OutputFormat::Toon => caliper_docgen_core::toon::render_output_toon(&output),
73	        };
74	
75	        match args.out {
76	            Some(ref path) => write_atomic(path, &json).into_diagnostic().wrap_err(format!("Writing to {path}"))?,
77	            None => println!("{json}"),
78	        }
79	    }
80	
81	    // Must run regardless of --json — this is the one thing CI actually
82	    // depends on the exit code for.
83	    let exit_code = output.exit_code(false);
84	    // The process ends right after this, and freeing a large project's output one allocation at a time is slower
85	    // than letting the OS reclaim it.
86	    std::mem::forget(output);
87	    Ok(exit_code)
88	}
