90	/// Resolve the components the structural pass found with TypeScript's checker and merge the answer over `output`. An
91	/// unavailable checker leaves `output` as it was, plus one diagnostic.
92	fn apply_semantic_backend(
93	    options: &caliper_docgen_core::pipeline::PipelineOptions,
94	    output: &mut caliper_docgen_core::types::ExtractionOutput,
95	) {
96	    let project_root = options
97	        .src_dirs
98	        .first()
99	        .and_then(|dir| caliper_docgen_core::canonical_path::canonicalize(dir).ok())
100	        .or_else(|| std::env::current_dir().ok().and_then(|dir| camino::Utf8PathBuf::from_path_buf(dir).ok()));
101	    let Some(project_root) = project_root else {
102	        let outcome = caliper_docgen_core::types::semantic::SemanticOutcome::unavailable("no project directory");
