121	/// Resolves the request's components with the checker. Blocks; builds its own single-threaded runtime, so it must
122	/// not be called from inside one.
123	pub fn resolve(request: SemanticRequest) -> SemanticOutcome {
124	    let runtime = match tokio::runtime::Builder::new_current_thread().enable_all().build() {
125	        Ok(runtime) => runtime,
126	        Err(error) => return SemanticOutcome::unavailable(format!("could not start an async runtime: {error}")),
127	    };
128	    runtime.block_on(run(request))
129	}
