34	/// One prop as the checker reports it.
35	#[derive(Debug, Clone, PartialEq)]
36	pub struct SemanticProp {
37	    /// The prop's name as written in the props type.
38	    pub name: String,
39	    /// The type the checker computed for it, in the same shape the structural resolver produces.
40	    pub prop_type: PropType,
41	    /// Whether the checker found the prop non-optional.
42	    pub required: bool,
43	    /// The prop's JSDoc description, empty when it has none; the merge then keeps the structural description.
44	    pub description: String,
45	    /// Declared by `@types/react` (`children`, `aria-*`, handlers, `className`): not the component's own prop.
46	    pub react_declared: bool,
47	}
