49	impl SemanticProp {
50	    fn structural_hash(&self) -> u64 {
51	        let mut hasher = FxHasher::default();
52	        self.name.hash(&mut hasher);
53	        self.required.hash(&mut hasher);
54	        self.react_declared.hash(&mut hasher);
55	        self.description.hash(&mut hasher);
56	        self.prop_type.structural_hash(&mut hasher);
57	        hasher.finish()
58	    }
59	}
