124	    /// The component's name, as the structural pass reported it.
125	    pub display_name: String,
126	    /// Whether the module exports the component, by name or as `default`. The checker answers only for exported
127	    /// ones and reports the rest as fallbacks.
128	    pub exported: bool,
129	    /// Props the structural pass already has a description for. The checker is not asked for those: it is 65% of
130	    /// the requests on Mantine, and the merge keeps the structural description when the checker's is empty.
131	    pub described: rustc_hash::FxHashSet<String>,
132	    /// Which props `@types/react` declares the checker reports: `None` for all of them, else only these names. The
133	    /// session decides from `htmlAttributes` (`react_types::react_props_wanted`); the checker never filters by itself.
134	    pub react_wanted: Option<rustc_hash::FxHashSet<String>>,
135	}
