147	impl SemanticOutcome {
148	    /// An outcome for a backend that did nothing: the structural result stands, for this reason.
149	    pub fn unavailable(reason: impl Into<String>) -> Self {
150	        let diagnostic = Diagnostic::new(
151	            DiagnosticSeverity::Warning,
152	            DiagnosticCode::SemanticBackend,
153	            format!("TypeScript checker backend unavailable: {}", reason.into()),
154	        )
155	        .with_help(
156	            "The structural result is used instead. Install `typescript@beta` (7.1) or `tsrs`, or pass `--tsc-path`.",
157	        );
