1	#![allow(clippy::unwrap_used, clippy::expect_used, clippy::print_stdout, clippy::print_stderr)]
2	//! The two measurable ADR 0026 gates before the checker becomes the default, through the session a Storybook addon runs:
3	//! a lazy `WatchSession` asking a warm `OnDemand` over the project's own `tsc` (`just gate-measure` runs both).
4	//!
5	//!   gate_harness memory      --src DIR --tsc PATH [--edits 650] [--max-rss-mib N]
6	//!   gate_harness determinism --src DIR --tsc PATH [--components 150] [--threads 1,2,4] [--runs 3]
7	//!
8	//! `memory` rewrites one component's file, tells the session, and asks for the component, `--edits` times; it samples the
9	//! checker's PID and resident memory after every answer and prints the recycles, the peak, and whether the last answer
10	//! equals a fresh session's. `determinism` asks a fresh checker for the same components under each `RAYON_NUM_THREADS`
11	//! (tsrs's `--api` has no checker-count flag; see docs/gate-measurements.md), `--runs` times each, alternating the query
12	//! order, and byte-compares every output. Each prints one JSON line and exits 1 on a failed check.
13	use std::collections::BTreeSet;
14	use std::process::Command;
15	use std::sync::Arc;
16	use std::time::Duration;
17	
18	use caliper_docgen_core::pipeline::{CollapseInheritedProps, ComponentAnswer, PipelineOptions, WatchSession};
19	use caliper_docgen_core::types::semantic::SemanticProvider;
20	use caliper_docgen_semantic::{OnDemand, OnDemandConfig};
21	use camino::Utf8PathBuf;
22	
23	const CHECKER_NOTE: &str = "resolved by the TypeScript checker";
24	
25	fn arg(args: &[String], name: &str) -> Option<String> {
26	    args.iter().position(|a| a == name).and_then(|at| args.get(at + 1)).cloned()
27	}
28	
29	/// A lazy session with a warm checker, configured as the addon configures it (dependencies loaded, nothing collapsed).
30	fn open(
31	    src: &Utf8PathBuf,
32	    tsc: &str,
33	    env: Vec<(String, String)>,
34	    max_rss_mib: Option<u64>,
35	) -> (WatchSession, Arc<OnDemand>) {
36	    let mut config = OnDemandConfig::new(src.clone());
37	    config.tsconfig = src.ancestors().map(|dir| dir.join("tsconfig.json")).find(|file| file.is_file());
38	    config.tsc_path = Some(Utf8PathBuf::from(tsc));
39	    config.request_timeout = Duration::from_secs(120);
40	    config.extra_env = env;
41	    config.max_rss_mib = max_rss_mib.unwrap_or(config.max_rss_mib);
42	    let checker = Arc::new(OnDemand::new(config));
43	    let options = PipelineOptions {
44	        src_dirs: vec![src.clone()],
45	        load_dependencies: true,
46	        collapse_inherited_props: CollapseInheritedProps::None,
47	        ..PipelineOptions::default()
48	    };
49	    let session = WatchSession::lazy(options).with_semantic(checker.clone(), Duration::from_secs(120));
50	    drop(session.initialize());
51	    (session, checker)
52	}
53	
54	fn by_checker(answer: &ComponentAnswer) -> bool {
55	    answer.diagnostics.iter().any(|d| d.message.contains(CHECKER_NOTE))
56	}
57	
58	/// Resident MiB and thread count of a process, from `ps`; `None` once it has gone.
59	fn process_stats(pid: u32) -> Option<(u64, usize)> {
60	    let ps = |args: &[&str]| {
61	        let out = Command::new("ps").args(args).arg("-p").arg(pid.to_string()).output().ok()?;
62	        out.status.success().then(|| String::from_utf8_lossy(&out.stdout).into_owned())
63	    };
64	    let rss: u64 = ps(&["-o", "rss="])?.trim().parse().ok()?;
65	    Some((rss / 1024, ps(&["-M"])?.lines().count().saturating_sub(1)))
66	}
67	
68	fn edit_source(n: usize) -> String {
69	    format!(
70	        "import type {{ ButtonProps }} from '@chakra-ui/react'\nexport function GateEdited(props: ButtonProps & {{ edit{n}: string }}) {{\n  return null\n}}\n"
71	    )
72	}
73	
74	fn memory(src: &Utf8PathBuf, tsc: &str, edits: usize, max_rss_mib: Option<u64>) -> bool {
75	    let file = src.join("GateEdited.tsx");
76	    std::fs::write(&file, edit_source(0)).unwrap();
77	    let (session, checker) = open(src, tsc, Vec::new(), max_rss_mib);
78	    let (mut processes, mut peak, mut answered, mut stale) = (BTreeSet::new(), 0, 0, 0);
79	    for n in 1..=edits {
80	        std::fs::write(&file, edit_source(n)).unwrap();
81	        session.update_file(&file);
82	        let answer = session.component("GateEdited").expect("GateEdited is a component");
83	        // The answer must be the checker's, for this edit: a structural fallback would measure nothing.
84	        answered += usize::from(by_checker(&answer));
85	        stale += usize::from(!answer.entry.props.contains_key(&format!("edit{n}")));
86	        if let Some(pid) = checker.process_id() {
87	            processes.insert(pid);
88	            peak = peak.max(process_stats(pid).map_or(0, |(mib, _)| mib));
89	        }
90	    }
91	    // A replacement follows the reply it is due after, so one more request settles the counters.
92	    drop(checker.request(Vec::new()).recv_timeout(Duration::from_secs(120)));
93	    let last = session.component("GateEdited").unwrap();
94	    let (fresh_session, _fresh) = open(src, tsc, Vec::new(), None);
95	    let fresh = fresh_session.component("GateEdited").unwrap();
96	    let recycles = checker.recycles();
97	    let ok = answered == edits && stale == 0 && last == fresh;
98	    println!(
99	        "{{\"gate\":\"memory\",\"edits\":{edits},\"maxRssMib\":{},\"answeredByChecker\":{answered},\"staleAnswers\":{stale},\"processes\":{},\"recycles\":{{\"worn\":{},\"bloated\":{}}},\"peakRssMib\":{peak},\"finalEqualsFresh\":{},\"ok\":{ok}}}",
100	        max_rss_mib.map_or("null".to_string(), |mib| mib.to_string()),
101	        processes.len(),
102	        recycles.worn,
103	        recycles.bloated,
104	        last == fresh,
105	    );
106	    ok
107	}
108	
109	fn determinism(src: &Utf8PathBuf, tsc: &str, components: usize, threads: &[String], runs: usize) -> bool {
110	    let (probe, _checker) = open(src, tsc, Vec::new(), None);
111	    let mut keys = probe.component_keys();
112	    keys.retain(|key| key != "GateEdited");
113	    keys.sort();
114	    let step = (keys.len() / components.max(1)).max(1);
