1	// The structural comparison behind src/oracle.ts: both sides' prop types reduced to one shape, and one verdict per
2	// pair. Pure: nothing here talks to the checker.
3	
4	/** The primitive a literal is a value of: `"0"` and `0` spell the same `value` and are two types. */
5	export type LiteralKind = 'string' | 'number' | 'bigint' | 'boolean'
6	
7	/** A type reduced to what both sides can state: kind, literal value, members, fields, parameters. `alias` is the
8	 * checker's name for it (an alias, or the interface that declares it), which Caliper may print instead. */
9	export type Norm = (
10	  | { k: 'prim'; name: string }
11	  | { k: 'lit'; value: string; of: LiteralKind }
12	  | { k: 'union'; members: Norm[] }
13	  | { k: 'intersection'; members: Norm[] }
14	  | { k: 'array'; element: Norm }
15	  | { k: 'tuple'; elements: Norm[] }
16	  | { k: 'function'; params: { optional: boolean; rest: boolean; type: Norm }[]; returns: Norm }
17	  | { k: 'object'; fields: string[]; index: boolean; indexValue?: Norm }
18	  | { k: 'name'; name: string }
19	  | { k: 'param'; name: string; fallback?: Norm; constraint?: Norm }
20	  | { k: 'opaque' }
21	  | { k: 'error' }
22	) & { alias?: string }
23	
24	export type Verdict = 'identical' | 'spelled' | 'less precise' | 'wrong' | 'checker any/error'
25	
26	export const MAX_DEPTH = 3
27	export const VERDICTS: Verdict[] = ['identical', 'spelled', 'less precise', 'wrong', 'checker any/error']
28	const RANK: Verdict[] = ['identical', 'spelled', 'less precise', 'wrong']
29	
30	/** A type name without `React.` or a namespace qualifier. */
31	export const bareName = (name: string) => name.replace(/^.*\./, '')
32	export const prim = (name: string): Norm => ({ k: 'prim', name })
33	export const lit = (value: string, of: LiteralKind): Norm => ({ k: 'lit', value, of })
34	
35	/** `{}`: an object with no property and no index signature. The one place that decides it, for every reader of a
36	 * `Norm`: an index-only object (`{ [key: string]: V }`) has no fields either, and is not empty. */
37	export const isBareObject = (m: Norm) => m.k === 'object' && m.fields.length === 0 && !m.index
38	
39	const worst = (vs: Verdict[]): Verdict => vs.reduce((a, b) => (RANK.indexOf(b) > RANK.indexOf(a) ? b : a), 'identical')
40	const best = (vs: Verdict[]): Verdict => vs.reduce((a, b) => (RANK.indexOf(b) < RANK.indexOf(a) ? b : a), 'wrong')
41	const isBool = (n: Norm, value: string) => n.k === 'lit' && n.of === 'boolean' && n.value === value
42	const isUndefined = (m: Norm) => m.k === 'prim' && m.name === 'undefined'
43	const WIDENING = new Set(['string', 'number', 'boolean'])
44	
45	/** An empty object type, or `Record<…>` (its arguments are not kept): what `string & {}` intersects with. */
46	const isEmptyObject = (m: Norm) => isBareObject(m) || (m.k === 'name' && m.name === 'Record')
47	
48	/** Whether `m` is the primitive `name`, or `name & {}`, or a union with either. */
49	function absorbs(m: Norm, name: string): boolean {
50	  if (m.k === 'prim') return m.name === name
51	  if (m.k === 'union') return m.members.some((member) => absorbs(member, name))
52	  return m.k === 'intersection' && m.members.some(isEmptyObject) && m.members.some((member) => absorbs(member, name))
53	}
54	
55	/** A name or opaque type that Caliper (or the checker) did not expand: what it holds is unknown, so no member beside it
56	 * can prove the other side wrong. */
57	const isUnexpanded = (m: Norm) => m.k === 'name' || m.k === 'opaque'
58	
59	/** Union members without `undefined` (an optional prop's, which both sides treat as optional), flattened, with
60	 * `true | false` as `boolean`. */
61	function members(n: Norm, coverLiterals = false): Norm[] {
62	  const flat: Norm[] = []
63	  const push = (m: Norm) => {
64	    if (m.k === 'union') m.members.forEach(push)
65	    // An optional generic prop reads `T | (undefined & T)`.
66	    else if (!isUndefined(m) && !(m.k === 'intersection' && m.members.some(isUndefined))) flat.push(m)
67	  }
68	  push(n)
69	  // `'default' | 'large' | string` is `string` to the checker: a literal that a primitive of its kind in the same
70	  // union already covers adds nothing, so a union written with it holds the same values as one without. The checker's
71	  // `"blue" | … | (string & {})` keeps its literals for the reader, so `compare` scores it spelled, not identical. A
72	  // literal is covered by the primitive of its own kind only: `"0"` is not covered by `number`, `true` not by `string`.
73	  // `string & {}` and `string & Record<never, never>` (the `LiteralUnion` spellings) are `string` for this purpose.
74	  const has = (name: string) => flat.some((m) => absorbs(m, name))
75	  const covered = (m: Norm) => coverLiterals && m.k === 'lit' && has(m.of)
76	  const kept = flat.filter((m) => !covered(m))
77	  if (kept.some((m) => isBool(m, 'true')) && kept.some((m) => isBool(m, 'false'))) {
78	    return [...kept.filter((m) => !isBool(m, 'true') && !isBool(m, 'false')), prim('boolean')]
79	  }
80	  return kept
81	}
82	
83	/** Two unions: each checker member covered by one of Caliper's (a missing member makes Caliper's type too narrow),
84	 * and each of Caliper's matched by one of the checker's (an extra member makes it too wide, unless it widens
85	 * literals). */
86	function compareUnions(cm: Norm[], km: Norm[], depth: number): Verdict {
87	  const kCovered = km.map((m) => best(cm.map((cMember) => compare(cMember, m, depth + 1))))
88	  const cMatched = cm.map((m) => {
89	    const verdict = best(km.map((kMember) => compare(m, kMember, depth + 1)))
90	    const widens =
91	      m.k === 'prim' &&
92	      WIDENING.has(m.name) &&
93	      km.some((kMember) => kMember.k === 'lit' || (kMember.k === 'prim' && kMember.name === m.name))
94	    return verdict === 'wrong' && widens ? 'less precise' : verdict
95	  })
96	  const verdict = worst([...kCovered, ...cMatched])
97	  // A union with a name or opaque member (`MantineColor | 'initials'`, a template literal) may hold the other side's
98	  // values in that member, so a member it cannot match is not proof of a different type.
99	  return verdict === 'wrong' && [...cm, ...km].some((m) => isUnexpanded(m)) ? 'less precise' : verdict
100	}
101	
102	function compareFunctions(c: Norm & { k: 'function' }, k: Norm & { k: 'function' }, depth: number): Verdict {
103	  const verdicts: Verdict[] = [compare(c.returns, k.returns, depth + 1)]
104	  for (const [i, kp] of k.params.entries()) {
105	    const cp = c.params[i]
106	    if (cp === undefined) {
107	      verdicts.push(kp.optional || kp.rest ? 'less precise' : 'wrong')
108	    } else {
109	      verdicts.push(compare(cp.type, kp.type, depth + 1))
110	      // A marker the checker has and this side lost.
111	      if ((kp.optional && !cp.optional) || (kp.rest && !cp.rest)) verdicts.push('less precise')
112	    }
113	  }
114	  if (c.params.length > k.params.length) verdicts.push('wrong')
115	  return worst(verdicts)
116	}
117	
118	/** One non-union type against another. */
119	function compareOne(c: Norm, k: Norm, depth: number): Verdict {
120	  switch (k.k) {
121	    case 'prim': {
122	      return c.k === 'prim' && c.name === k.name ? 'identical' : 'wrong'
123	    }
124	    case 'lit': {
125	      if (c.k === 'lit') return c.value === k.value && c.of === k.of ? 'identical' : 'wrong'
126	      return c.k === 'prim' && WIDENING.has(c.name) ? 'less precise' : 'wrong'
127	    }
128	    case 'array': {
129	      return c.k === 'array' ? compare(c.element, k.element, depth + 1) : 'wrong'
130	    }
131	    case 'tuple': {
132	      if (c.k !== 'tuple') return c.k === 'array' ? 'less precise' : 'wrong'
133	      if (c.elements.length !== k.elements.length) return 'wrong'
134	      return worst(c.elements.map((e, i) => compare(e, k.elements[i], depth + 1)))
135	    }
136	    case 'function': {
137	      return c.k === 'function' ? compareFunctions(c, k, depth) : 'wrong'
138	    }
139	    case 'object': {
140	      if (c.k !== 'object') return c.k === 'prim' && c.name === 'object' ? 'less precise' : 'wrong'
141	      const own = new Set(c.fields)
142	      if (c.fields.some((f) => !k.fields.includes(f))) return 'wrong'
143	      // An index signature Caliper has and the checker does not describes a different type.
144	      if (c.index && !k.index) return 'wrong'
145	      const verdicts: Verdict[] = [
146	        k.fields.some((f) => !own.has(f)) || (k.index && !c.index) ? 'less precise' : 'identical',
147	      ]
148	      // Both state an index: its value type is compared, and one a side does not state is not proof of agreement.
149	      if (c.index && k.index) {
150	        verdicts.push(c.indexValue && k.indexValue ? compare(c.indexValue, k.indexValue, depth + 1) : 'less precise')
151	      }
152	      return worst(verdicts)
153	    }
154	    case 'intersection': {
155	      if (c.k !== 'intersection') return 'less precise'
156	      return c.members.length === k.members.length ? 'identical' : 'less precise'
157	    }
158	    case 'param': {
159	      // A type parameter of the component itself, which Caliper replaced with an instantiation: its default, as a bare
160	      // `AccordionProps` means `AccordionProps<false>`, or its constraint. That is one instance of the parameter,
161	      // looser or narrower than the parameter itself, and not another type; a type that is neither instance is.
162	      // `c` may be one member of a union Caliper wrote out (`string` of `string | number`), so it must fit one member of
163	      // an instance, not all of them.
164	      const instances = [k.fallback, k.constraint].filter((i): i is Norm => i !== undefined).flatMap((i) => members(i))
165	      // A parameter with neither (a generic component cast over `forwardRef`, whose props interface declares the
166	      // default) leaves the checker no instance to hold Caliper's to: any one it picked is one value of the parameter.
167	      if (instances.length === 0) return 'less precise'
168	      return instances.some((i) => compare(c, i, depth + 1) !== 'wrong') ? 'less precise' : 'wrong'
169	    }
170	    default: {
171	      return 'wrong'
172	    }
173	  }
174	}
175	
176	/** How Caliper's normalized type `c` stands against the checker's `k`. A checker union that spells literals a
177	 * primitive in it already covers (`'a' | 'b' | (string & {})`) holds the values Caliper's `string` does, spelled
178	 * another way. */
179	export function compare(c: Norm, k: Norm, depth = 0): Verdict {
180	  const verdict = compareValues(c, k, depth)
181	  return verdict === 'identical' && members(k).length !== members(k, true).length ? 'spelled' : verdict
182	}
183	
